// src/config.defaults.js
//
// Master defaults for the RepLog frontend.
// These values can be overridden by config.yaml at the project root.
// The Vite build merges both into virtual:app-config.
// Do NOT edit this file to change settings — use config.yaml instead.

const config = {
  // ── API ─────────────────────────────────────────────────────────────────
  apiBase: "/api",

  // ── Sync queue ─────────────────────────────────────────────────────────
  // Event-driven triggers only (new entity, login, logout) — no polling.
  sync: {
    maxRetries: 100,
    logoutPushTimeoutMs: 2500,
    requestTimeoutMs: 20000,
  },

  // ── Health check ───────────────────────────────────────────────────────
  health: {
    cacheMs: 5000,
    fetchTimeoutMs: 3000,
    pollIntervalMs: 30_000,
  },

  // ── Entries ────────────────────────────────────────────────────────────
  entries: {
    defaultLimit: 10,
    capLimit: 10,
    loadMoreLimit: 200,
  },

  // ── Storage keys ───────────────────────────────────────────────────────
  storage: {
    settingsKey: "replog-ui-settings",
  },
};

export default config;
